import assert from "node:assert/strict";
import {
  mkdtempSync,
  mkdirSync,
  copyFileSync,
  rmSync,
  readdirSync,
  cpSync,
} from "node:fs";
import { tmpdir } from "node:os";
import test from "node:test";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..");

test("site data loads when the generated profiles.json is absent", async () => {
  // src/content/ is gitignored and generated by `npm run sync:content`, so a
  // fresh clone has none of it. site.js resolves ../../content/profiles.json
  // relative to itself, so a copy in a sandbox with no src/content/ is the
  // fresh-clone state. It used to readFileSync unguarded there and throw at
  // data-import time, aborting the whole Eleventy build.
  const sandbox = mkdtempSync(join(tmpdir(), "site-data-"));
  try {
    const dataDir = join(sandbox, "src", "eleventy", "_data");
    mkdirSync(dataDir, { recursive: true });
    cpSync(join(repo, "src", "lib"), join(sandbox, "src", "lib"), {
      recursive: true,
    });

    copyFileSync(
      join(repo, "src", "eleventy", "_data", "site.js"),
      join(dataDir, "site.js"),
    );

    // Sanity: the sandbox must genuinely lack src/content, else this tests nothing.
    assert.equal(readdirSync(join(sandbox, "src")).includes("content"), false);

    const { default: site } = await import(
      pathToFileURL(join(dataDir, "site.js")).href
    );
    assert.equal(typeof site, "object", "site data must export an object");
    assert.ok(
      site.scholarUrl.startsWith("https://scholar.google.com/citations"),
      `unexpected scholarUrl: ${site.scholarUrl}`,
    );
    // The profile id is absent, so no "?user=" query may be emitted.
    assert.ok(
      !site.scholarUrl.includes("?user="),
      `unexpected scholar query: ${site.scholarUrl}`,
    );
  } finally {
    rmSync(sandbox, { recursive: true, force: true });
  }
});
